INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4400, 'narrow', '/ˈnæroʊ/', 'adjective', '{"zh-TW":["狹窄的","有限的；勉強的"],"en":["small in width","limited in range"]}', '{"root":{"text":"narr","meaning":"tight (緊的)"}}', 'narrow down / narrow margin / narrow escape', '[{"en":"The road was too narrow for two cars.","zh-TW":"這條路太窄了，容不下兩輛車。"},{"en":"We need to narrow down the candidates.","zh-TW":"我們需要縮小候選人範圍。"}]', '{"verb":"narrow","adverb":"narrowly","noun":"narrowness"}', NULL, 2, 4400, NULL),
(4401, 'national park', '/''næʃənəl pɑːrk/', 'noun', '{"zh-TW":["國家公園"],"en":["a large area of land protected by the government for its natural beauty or ecological importance"]}', NULL, 'visit a national park / national park permit / national park trail', '[{"en":"The national park attracts millions of visitors every year.","zh-TW":"國家公園每年吸引數百萬遊客。"},{"en":"Camping is permitted in designated areas within the national park.","zh-TW":"在國家公園內的指定區域允許露營。"}]', NULL, NULL, 5, 4401, NULL),
(4402, 'nationalization', '/ˌnæʃənəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["國有化"],"en":["the process of taking private industry into state ownership"]}', NULL, 'bank nationalization / industry nationalization / resist nationalization', '[{"en":"The government nationalized the railway to improve service and reduce fares.","zh-TW":"政府將鐵路國有化，以改善服務並降低票價。"},{"en":"Nationalization of the oil industry was controversial but increased state revenues.","zh-TW":"石油工業的國有化頗具爭議，但增加了國家收入。"}]', '{"verb":"nationalize","adjective":"nationalized"}', NULL, 5, 4402, NULL),
(4403, 'native speaker', '/''neɪtɪv ˌspiːkər/', 'noun', '{"zh-TW":["母語使用者；本語者"],"en":["a person who has spoken a particular language as their first language from early childhood"]}', NULL, 'consult a native speaker / native speaker level / native speaker accent', '[{"en":"She practiced English with a native speaker to improve her fluency and accent.","zh-TW":"她與母語使用者一起練習英語，以提高她的流利度和口音。"},{"en":"Companies prefer hiring native speakers for translation and proofreading work.","zh-TW":"公司傾向於聘請母語使用者從事翻譯和校對工作。"}]', NULL, NULL, 5, 4403, NULL),
(4404, 'natural', 'ˈnætʃərəl', 'adjective', '{"zh-TW":["自然的；天然的","本能的"],"en":["existing in nature","normal and expected"]}', NULL, 'natural resource/natural talent', '[{"en":"She has a natural talent for management.","zh-TW":"她有管理方面的天賦。"}]', '{"noun":"nature","adverb":"naturally"}', NULL, 3, 4404, NULL),
(4405, 'natural disaster', '/ˈnætʃərəl dɪˈzɑːstər/', 'noun', '{"zh-TW":["天然災害；自然災難"],"en":["a catastrophic event caused by natural forces"]}', NULL, 'respond to a natural disaster / natural disaster relief', '[{"en":"The earthquake was one of the worst natural disasters in decades.","zh-TW":"這次地震是幾十年來最嚴重的天然災害之一。"},{"en":"International aid arrived quickly after the natural disaster.","zh-TW":"自然災難後，國際援助迅速到達。"}]', NULL, NULL, 5, 4405, NULL),
(4406, 'nature', '/ˈneɪtʃər/', 'noun', '{"zh-TW":["自然；本質"],"en":["the physical world","the basic character of something"]}', NULL, 'by nature / nature of business', '[{"en":"What is the nature of your business?","zh-TW":"你的業務性質是什麼？"},{"en":"He is competitive by nature.","zh-TW":"他天性好勝。"}]', '{"noun":"nature","adjective":"natural","adverb":"naturally"}', NULL, 2, 4406, NULL),
(4407, 'nature reserve', '/''neɪtʃər rɪˈzɜːv/', 'noun', '{"zh-TW":["自然保護區"],"en":["an area of land managed to protect its wildlife, plants, and natural features"]}', NULL, 'visit a nature reserve / protect a nature reserve / national nature reserve', '[{"en":"The nature reserve is home to hundreds of bird species.","zh-TW":"這個自然保護區是數百種鳥類的家園。"},{"en":"Visitors to the nature reserve must stay on designated trails.","zh-TW":"自然保護區的遊客必須走指定步道。"}]', NULL, NULL, 5, 4407, NULL),
(4408, 'nature-based solutions', '/ˈneɪtʃər beɪst səˈluːʃənz/', 'noun', '{"zh-TW":["自然解決方案"],"en":["strategies that use natural processes to address environmental challenges"]}', NULL, 'implement nature-based solutions / nature-based solutions for climate / nature-based solutions framework', '[{"en":"Nature-based solutions such as mangrove restoration help protect coastlines.","zh-TW":"紅樹林恢復等自然解決方案有助於保護海岸線。"},{"en":"Nature-based solutions can be more cost-effective than engineered alternatives.","zh-TW":"自然解決方案比工程替代方案更具成本效益。"}]', NULL, NULL, 5, 4408, NULL),
(4409, 'navigate', '/''nævɪɡeɪt/', 'verb', '{"zh-TW":["導航；引航；找路"],"en":["to plan and direct a route or journey; to find one''s way"]}', NULL, 'navigate by / navigate through / navigate a route', '[{"en":"She used a compass to navigate through the dense forest.","zh-TW":"她使用指南針在茂密的森林中找路。"},{"en":"Navigating the winding streets of the old city was a challenge.","zh-TW":"在老城蜿蜒的街道中找路是一個挑戰。"}]', '{"noun":"navigation","adjective":"navigable"}', NULL, 3, 4409, NULL),
(4410, 'navigate uncertainty', '/''nævɪˌɡeɪt ʌnˈsɜːrtənti/', 'phrase', '{"zh-TW":["應對不確定性；在不確定中前進"],"en":["to manage or find one''s way through unclear or unpredictable situations"]}', NULL, 'navigate uncertainty effectively / ability to navigate uncertainty', '[{"en":"Leaders who can navigate uncertainty inspire confidence during difficult times.","zh-TW":"能夠應對不確定性的領導者在困難時期能激發信心。"},{"en":"The team developed strategies to navigate uncertainty during the supply chain crisis.","zh-TW":"團隊在供應鏈危機期間制定了應對不確定性的策略。"}]', NULL, NULL, 5, 4410, NULL),
(4411, 'NDA', '/ɛn diː eɪ/', 'noun', '{"zh-TW":["保密協議"],"en":["a contract restricting disclosure of confidential information"]}', NULL, 'sign an NDA / breach an NDA', '[{"en":"All new employees must sign an NDA before starting.","zh-TW":"所有新員工在入職前必須簽署保密協議。"},{"en":"The NDA prevents either party from disclosing trade secrets.","zh-TW":"保密協議阻止任何一方披露商業機密。"}]', NULL, NULL, 1, 4411, NULL),
(4412, 'near', '/nɪr/', 'preposition', '{"zh-TW":["靠近；附近"],"en":["close to in distance or time"]}', NULL, 'near future / nearby', '[{"en":"Changes will happen in the near future.","zh-TW":"改變將在不久的將來發生。"},{"en":"Is there a restaurant nearby?","zh-TW":"附近有餐廳嗎？"}]', '{"preposition":"near","adjective":"near","adverb":"nearly","adjective2":"nearby"}', NULL, 1, 4412, NULL),
(4413, 'necessary', '/ˈnɛsəsɛri/', 'adjective', '{"zh-TW":["必要的"],"en":["needed; essential"]}', NULL, 'if necessary / necessary steps', '[{"en":"Take the necessary steps to fix this.","zh-TW":"採取必要措施來解決這個問題。"},{"en":"Overtime is sometimes necessary.","zh-TW":"加班有時是必要的。"}]', '{"adjective":"necessary","noun":"necessity","adverb":"necessarily","adjective2":"unnecessary"}', NULL, 3, 4413, 162),
(4414, 'neck', '/nɛk/', 'noun', '{"zh-TW":["脖子"],"en":["the part connecting the head to the body"]}', NULL, 'neck and neck / bottleneck', '[{"en":"The two companies are neck and neck.","zh-TW":"兩家公司不相上下。"},{"en":"Shipping is the bottleneck in our process.","zh-TW":"運輸是我們流程中的瓶頸。"}]', '{"noun":"neck","noun2":"necklace","noun3":"bottleneck"}', NULL, 1, 4414, NULL),
(4415, 'need', '/niːd/', 'verb', '{"zh-TW":["需要"],"en":["to require something"]}', NULL, 'in need of / need to', '[{"en":"We are in need of more staff.","zh-TW":"我們需要更多員工。"},{"en":"You need to sign this form.","zh-TW":"你需要簽署這份表格。"}]', '{"verb":"need","noun":"need","adjective":"needy","adjective2":"needless"}', NULL, 1, 4415, NULL),
(4416, 'negative carry', '/ˈneɡətɪv ˈkæri/', 'noun', '{"zh-TW":["負利差；持有成本高於收益"],"en":["a situation where the cost of holding an investment exceeds the income it generates"]}', NULL, 'negative carry trade / experience negative carry / negative carry position', '[{"en":"The bond trade resulted in negative carry due to the high funding cost.","zh-TW":"由於高融資成本，債券交易產生了負利差。"},{"en":"Investors accept negative carry if they expect capital appreciation.","zh-TW":"如果投資者預期資本增值，他們接受負利差。"}]', NULL, NULL, 5, 4416, NULL),
(4417, 'negative equity', '/ˈneɡətɪv ˈekwɪti/', 'noun', '{"zh-TW":["負資產；負淨值"],"en":["when the value of an asset falls below the amount owed on it"]}', NULL, 'face negative equity / escape negative equity', '[{"en":"Homeowners in declining markets may find themselves in negative equity.","zh-TW":"在下跌市場中，房主可能發現自己陷入負資產。"},{"en":"Negative equity prevents the company from securing further financing.","zh-TW":"負資產阻止公司獲得進一步的融資。"}]', NULL, NULL, 5, 4417, NULL),
(4418, 'negative gearing', '/''neɡətɪv ˈɡɪərɪŋ/', 'noun', '{"zh-TW":["負扣稅；負攤提"],"en":["an investment strategy where costs exceed rental income, creating a tax-deductible loss"]}', NULL, 'use negative gearing / negative gearing strategy / benefit of negative gearing', '[{"en":"Investors use negative gearing to offset investment losses against taxable income.","zh-TW":"投資者使用負扣稅策略將投資損失抵消應稅收入。"},{"en":"Negative gearing is popular in markets where capital growth is expected.","zh-TW":"負扣稅在預期資本增值的市場中很受歡迎。"}]', NULL, NULL, 5, 4418, NULL),
(4419, 'neglect', '/nɪˈɡlekt/', 'verb, noun', '{"zh-TW":["忽略；疏忽"],"en":["to fail to care for or attend to"]}', NULL, 'neglect duties/responsibilities / suffer from neglect', '[{"en":"He neglected to inform the team about the change.","zh-TW":"他疏忽了通知團隊有關變更的事。"},{"en":"The equipment suffered from years of neglect.","zh-TW":"設備因多年疏於維護而受損。"}]', '{"noun":"neglect, negligence","verb":"neglect","adjective":"negligent"}', NULL, 3, 4419, NULL),
(4420, 'negotiate', '/nɪˈɡoʊʃieɪt/', 'verb', '{"zh-TW":["談判；協商","磋商","協商"],"en":["to try to reach an agreement through discussion","to discuss to reach an agreement","to deal with something","to reach an agreement through discussion"]}', '{"prefix":{"text":"neg-","meaning":"not (不)"},"root":{"text":"oti","meaning":"leisure (閒暇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"非閒暇之事（嚴肅處理），即「談判」。"}', 'negotiate a deal / negotiate terms / negotiate a contract; negotiate with sb. / negotiate a deal; negotiate terms / negotiate a salary', '[{"en":"The two sides are negotiating a peace agreement.","zh-TW":"雙方正在協商和平協議。"},{"en":"She negotiated a higher salary.","zh-TW":"她談判爭取到了更高的薪水。"},{"en":"The union is negotiating with management for better wages.","zh-TW":"工會正在與管理層協商更高的薪資。"},{"en":"We negotiated a 10% discount.","zh-TW":"我們談成了九折優惠。"},{"en":"She successfully negotiated better terms.","zh-TW":"她成功談成了更好的條件。"},{"en":"New hires can negotiate their salary.","zh-TW":"新員工可以協商薪資。"}]', '{"noun":"negotiation","noun2":"negotiator","adjective":"negotiable"}', NULL, 3, 4420, 39),
(4421, 'negotiation', '/nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["談判；協商"],"en":["a discussion aimed at reaching a mutually acceptable agreement"]}', NULL, 'contract negotiation / salary negotiation / enter negotiations / negotiation tactics', '[{"en":"The negotiation lasted three days before a deal was reached.","zh-TW":"談判持續了三天才達成協議。"},{"en":"Preparation is the key to successful negotiation.","zh-TW":"準備是成功談判的關鍵。"}]', '{"verb":"negotiate","noun":"negotiator","adjective":"negotiable"}', NULL, 4, 4421, 598),
(4422, 'negotiation skill', '/nɪˌɡəʊʃiˈeɪʃən skɪl/', 'noun', '{"zh-TW":["談判技巧；協商能力"],"en":["the ability to reach mutually acceptable agreements through discussion and compromise"]}', NULL, 'develop negotiation skills / strong negotiation skills / apply negotiation skills', '[{"en":"Strong negotiation skills helped her secure a higher salary than the initial offer.","zh-TW":"強大的談判技巧幫助她獲得了比最初報價更高的薪水。"},{"en":"Negotiation skills are among the most sought-after competencies in business professionals.","zh-TW":"談判技巧是商業專業人士中最受歡迎的能力之一。"}]', NULL, NULL, 5, 4422, NULL),
(4423, 'neighbor', '/ˈneɪbər/', 'noun', '{"zh-TW":["鄰居"],"en":["a person living next door or nearby"]}', NULL, 'next-door neighbor / neighborhood', '[{"en":"Our office neighbors are a law firm.","zh-TW":"我們辦公室的鄰居是一家律師事務所。"},{"en":"It is a friendly neighborhood for business.","zh-TW":"這是一個對商業友好的社區。"}]', '{"noun":"neighbor","noun2":"neighborhood","adjective":"neighboring"}', NULL, 3, 4423, NULL),
(4424, 'neoliberalism', '/ˌniːəʊˈlɪbərəlɪzəm/', 'noun', '{"zh-TW":["新自由主義"],"en":["a political ideology favoring free markets, deregulation, and reduced government intervention"]}', NULL, 'rise of neoliberalism / critique of neoliberalism / neoliberalism policies', '[{"en":"Critics of neoliberalism argue it exacerbated inequality and weakened social protections.","zh-TW":"新自由主義的批評者認為，它加劇了不平等並削弱了社會保護。"},{"en":"Neoliberalism dominated global economic policy from the 1980s through the early 2000s.","zh-TW":"新自由主義主導了一九八○年代至二○○○年代初的全球經濟政策。"}]', '{"adjective":"neoliberal","noun2":"neoliberal"}', NULL, 5, 4424, NULL),
(4425, 'nervous', '/ˈnɜːrvəs/', 'adjective', '{"zh-TW":["緊張的；神經質的"],"en":["easily worried or anxious"]}', '{"root":{"text":"nerv","meaning":"nerve (神經)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"神經緊繃的，即「緊張的」。"}', 'feel nervous / nervous about', '[{"en":"She was nervous before the presentation.","zh-TW":"她在報告前很緊張。"},{"en":"I always get nervous during exams.","zh-TW":"我考試時總是很緊張。"}]', '{"noun":"nervousness","adverb":"nervously"}', NULL, 3, 4425, NULL),
(4426, 'net', '/nɛt/', 'adjective', '{"zh-TW":["淨的；純的"],"en":["remaining after deductions"]}', '{"root":{"text":"net","meaning":"clean (乾淨的)"}}', 'net profit / net income / net worth', '[{"en":"The company reported a net profit of $2 million.","zh-TW":"公司報告了兩百萬美元的淨利潤。"},{"en":"What is your net income after taxes?","zh-TW":"你扣稅後的淨收入是多少？"}]', '{"noun":"net","verb":"net"}', NULL, 1, 4426, NULL),
(4427, 'net asset value', '/net ˈæset ˈvæljuː/', 'noun', '{"zh-TW":["淨資產價值"],"en":["the total assets minus total liabilities of a fund or company"]}', NULL, 'calculate net asset value / net asset value per share', '[{"en":"The fund''s net asset value increased by 8% over the quarter.","zh-TW":"基金的淨資產價值在本季度增加了8%。"},{"en":"Mutual fund units are priced based on daily net asset value.","zh-TW":"共同基金單位根據每日淨資產價值定價。"}]', '{"abbreviation":"NAV"}', NULL, 5, 4427, NULL),
(4428, 'net assets', '/net ˈæsets/', 'noun', '{"zh-TW":["淨資產"],"en":["total assets minus total liabilities"]}', NULL, 'increase net assets / net assets per share', '[{"en":"The company grew its net assets from 20 million to 50 million.","zh-TW":"公司的淨資產從2000萬元增長到5000萬元。"},{"en":"Net assets represent the book value of shareholders equity.","zh-TW":"淨資產代表股東權益的帳面價值。"}]', NULL, NULL, 4, 4428, NULL),
(4429, 'net cash flow', '/net kæʃ floʊ/', 'noun', '{"zh-TW":["淨現金流"],"en":["the total cash received minus total cash spent in a period"]}', NULL, 'calculate net cash flow / positive net cash flow', '[{"en":"A positive net cash flow indicates the business generates more than it spends.","zh-TW":"正的淨現金流表明業務產生的現金多於支出。"},{"en":"The project''s net cash flow was negative in the first year due to setup costs.","zh-TW":"由於設置成本，項目第一年的淨現金流為負。"}]', NULL, NULL, 5, 4429, NULL),
(4430, 'net income', '/nɛt ˈɪnkʌm/', 'noun', '{"zh-TW":["淨收入；淨利潤"],"en":["total earnings after all expenses and taxes are deducted"]}', NULL, 'report net income / net income growth', '[{"en":"The company reported a net income of $2 million last quarter.","zh-TW":"公司上季度報告淨收入為200萬美元。"},{"en":"Net income is a key measure of a company''s profitability.","zh-TW":"淨收入是衡量公司盈利能力的關鍵指標。"}]', NULL, NULL, 4, 4430, NULL),
(4431, 'net loss', '/nɛt lɒs/', 'noun', '{"zh-TW":["淨虧損"],"en":["the total loss after all expenses exceed all revenues"]}', NULL, 'report a net loss / recover from a net loss', '[{"en":"The company reported a net loss of five million this quarter.","zh-TW":"公司本季度報告淨虧損五百萬。"},{"en":"A net loss may require cost-cutting measures to restore profitability.","zh-TW":"淨虧損可能需要降低成本措施來恢復盈利能力。"}]', NULL, NULL, 3, 4431, NULL),
(4432, 'net margin', '/net ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["淨利率"],"en":["the percentage of revenue remaining after all expenses"]}', NULL, 'improve net margin / calculate net margin', '[{"en":"The net margin improved from 6% to 9% after cost cuts.","zh-TW":"成本削減後，淨利率從6%提高到了9%。"},{"en":"A higher net margin indicates more efficient operations.","zh-TW":"較高的淨利率表明運營效率更高。"}]', NULL, NULL, 4, 4432, NULL),
(4433, 'net present value', '/net ˈprezənt ˈvæljuː/', 'noun', '{"zh-TW":["淨現值"],"en":["the present value of future cash flows minus the initial investment"]}', NULL, 'calculate net present value / positive net present value', '[{"en":"A positive net present value indicates a worthwhile investment.","zh-TW":"正淨現值表示值得投資。"},{"en":"NPV analysis guided the decision to expand the factory.","zh-TW":"淨現值分析指導了擴建工廠的決策。"}]', '{"abbreviation":"NPV"}', NULL, 5, 4433, NULL),
(4434, 'net profit', '/net ˈprɒfɪt/', 'noun', '{"zh-TW":["淨利；稅後利潤"],"en":["profit remaining after all expenses and taxes are deducted"]}', NULL, 'net profit margin / report net profit', '[{"en":"Net profit for the year was $5.2 million.","zh-TW":"全年淨利潤為520萬美元。"},{"en":"Despite rising costs, net profit held steady.","zh-TW":"儘管成本上升，淨利潤保持穩定。"}]', NULL, NULL, 4, 4434, NULL),
(4435, 'net profit after tax', '/net ˈprɒfɪt ˌɑːftər tæks/', 'noun', '{"zh-TW":["稅後淨利潤"],"en":["the profit remaining after all expenses and taxes have been deducted"]}', NULL, 'report net profit after tax / increase net profit after tax', '[{"en":"Net profit after tax increased by 18% year over year.","zh-TW":"稅後淨利潤同比增長了18%。"},{"en":"Investors focus on net profit after tax as a true measure of profitability.","zh-TW":"投資者將稅後淨利潤作為盈利能力的真實衡量標準。"}]', '{"abbreviation":"NPAT"}', NULL, 5, 4435, NULL),
(4436, 'net profit margin', '/net ˈprɒfɪt ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["淨利率；淨利潤率"],"en":["the percentage of revenue remaining after all costs"]}', NULL, 'improve net profit margin / calculate net profit margin', '[{"en":"The company improved its net profit margin from 5% to 8%.","zh-TW":"公司將淨利率從5%提高到了8%。"},{"en":"A higher net profit margin indicates stronger financial efficiency.","zh-TW":"較高的淨利率表明更強的財務效率。"}]', NULL, NULL, 5, 4436, NULL),
(4437, 'net promoter score', '/net prəˈmoʊtər skɔːr/', 'noun', '{"zh-TW":["淨推薦值"],"en":["a metric measuring customer loyalty based on likelihood to recommend"]}', NULL, 'measure net promoter score / improve NPS / NPS survey', '[{"en":"Their net promoter score of 72 ranked among the industry''s best.","zh-TW":"他們72的淨推薦值在行業中名列前茅。"},{"en":"A high NPS indicates strong customer advocacy and satisfaction.","zh-TW":"高淨推薦值表明強大的客戶擁護和滿意度。"}]', '{"abbreviation":"NPS"}', NULL, 5, 4437, NULL),
(4438, 'net realizable value', '/net ˌriːəlaɪzəbl ˈvæljuː/', 'noun', '{"zh-TW":["淨變現價值"],"en":["the estimated selling price of an asset minus the costs to complete and sell it"]}', NULL, 'calculate net realizable value / value inventory at net realizable value', '[{"en":"Inventory is carried at the lower of cost or net realizable value.","zh-TW":"庫存以成本或淨變現價值中的較低者計列。"},{"en":"Net realizable value is key in testing inventory for impairment.","zh-TW":"淨變現價值是測試庫存減值的關鍵。"}]', '{"abbreviation":"NRV"}', NULL, 5, 4438, NULL),
(4439, 'net revenue', '/net ˈrevənjuː/', 'noun', '{"zh-TW":["淨收益；淨收入"],"en":["total revenue minus returns, discounts, and allowances"]}', NULL, 'report net revenue / grow net revenue', '[{"en":"Net revenue grew 12% after the new pricing strategy was implemented.","zh-TW":"實施新定價策略後，淨收益增長了12%。"},{"en":"Net revenue provides a more accurate picture of actual sales performance.","zh-TW":"淨收益提供了對實際銷售業績更準確的描述。"}]', '{"synonym":"net sales"}', NULL, 4, 4439, NULL),
(4440, 'net working capital', '/net ˈwɜːrkɪŋ ˈkæpɪtl/', 'noun', '{"zh-TW":["淨營運資金"],"en":["current assets minus current liabilities"]}', NULL, 'improve net working capital / positive net working capital', '[{"en":"Positive net working capital means the company can meet short-term obligations.","zh-TW":"正的淨營運資金意味著公司能夠履行短期義務。"},{"en":"The acquisition improved the buyer''s net working capital position.","zh-TW":"收購改善了買方的淨營運資金狀況。"}]', NULL, NULL, 5, 4440, NULL),
(4441, 'net working capital ratio', '/net ˈwɜːrkɪŋ ˈkæpɪtl ˈreɪʃioʊ/', 'noun', '{"zh-TW":["淨營運資金比率"],"en":["current assets minus current liabilities as a ratio to annual sales"]}', NULL, 'calculate net working capital ratio / improve the ratio', '[{"en":"A strong net working capital ratio indicates good short-term solvency.","zh-TW":"強勁的淨營運資金比率表明良好的短期償付能力。"},{"en":"The company improved its net working capital ratio by tightening receivables.","zh-TW":"公司通過收緊應收帳款改善了淨營運資金比率。"}]', NULL, NULL, 5, 4441, NULL),
(4442, 'net zero', '/nɛt ˈzɪərəʊ/', 'noun', '{"zh-TW":["淨零排放"],"en":["achieving a balance between greenhouse gas emissions and removals"]}', NULL, 'achieve net zero / net zero commitment', '[{"en":"Many countries have pledged to reach net zero by 2050.","zh-TW":"許多國家承諾到2050年實現淨零排放。"},{"en":"Net zero requires both reducing emissions and capturing carbon.","zh-TW":"淨零排放需要同時減少排放量和捕獲碳。"}]', NULL, NULL, 3, 4442, NULL),
(4443, 'net zero emissions', '/nɛt ˈzɪərəʊ ɪˈmɪʃənz/', 'noun', '{"zh-TW":["淨零排放"],"en":["achieving a balance between greenhouse gas emissions produced and removed"]}', NULL, 'commit to net zero emissions / achieve net zero emissions', '[{"en":"The company committed to net zero emissions by 2040.","zh-TW":"公司承諾到2040年實現淨零排放。"},{"en":"Net zero emissions require both reducing and offsetting carbon.","zh-TW":"淨零排放需要同時減少和抵消碳排放。"}]', NULL, NULL, 5, 4443, NULL),
(4444, 'netting', '/ˈnetɪŋ/', 'noun', '{"zh-TW":["軋差；淨額結算"],"en":["offsetting amounts owed by each party to calculate a single net amount"]}', NULL, 'currency netting / netting agreement / netting arrangement', '[{"en":"Intercompany netting reduced the number of cross-border payments.","zh-TW":"公司間軋差減少了跨境付款的次數。"},{"en":"A netting agreement between the two banks simplified settlement.","zh-TW":"兩家銀行之間的淨額結算協議簡化了結算。"}]', '{"verb":"net","adjective":"netted"}', NULL, 3, 4444, NULL),
(4445, 'network', '/ˈnɛtwɜːrk/', 'noun', '{"zh-TW":["網路；人脈","網路；網絡","人脈"],"en":["a system of connected computers or people","a system of connected things","a group exchanging information"]}', '{"root":{"text":"net","meaning":"mesh (網)"},"suffix":{"text":"work","meaning":"結構"}}', 'social network / network connection; build a network / social network', '[{"en":"The network is down.","zh-TW":"網路斷了。"},{"en":"Networking is important for your career.","zh-TW":"建立人脈對職業很重要。"},{"en":"She built an extensive professional network.","zh-TW":"她建立了廣泛的專業人脈。"},{"en":"The company is upgrading its computer network.","zh-TW":"公司正在升級電腦網路。"}]', '{"verb":"network","noun2":"networking","noun":"networking, networker"}', NULL, 3, 4445, 397),
(4446, 'networking', '/ˈnetwɜːrkɪŋ/', 'noun', '{"zh-TW":["人際網絡建立；交流"],"en":["building professional relationships for mutual benefit and opportunity"]}', NULL, 'professional networking / networking event / networking skills / expand your network', '[{"en":"Networking at industry conferences led to a new client contract.","zh-TW":"在行業會議上建立人際關係帶來了新客戶合同。"},{"en":"LinkedIn is the most widely used platform for professional networking.","zh-TW":"LinkedIn是最廣泛使用的職業網絡平台。"}]', '{"verb":"network","noun":"networker"}', NULL, 4, 4446, NULL),
(4447, 'neural network', '/ˈnjʊərəl ˈnetwɜːrk/', 'noun', '{"zh-TW":["神經網路"],"en":["a computing system modeled on the brain, used in machine learning"]}', NULL, 'train a neural network / neural network architecture / convolutional neural network', '[{"en":"The neural network was trained on millions of labeled images.","zh-TW":"神經網路在數百萬張有標籤的圖像上進行訓練。"},{"en":"Deep neural networks outperform traditional algorithms in speech recognition.","zh-TW":"深度神經網路在語音識別方面優於傳統算法。"}]', NULL, NULL, 5, 4447, NULL),
(4448, 'neurodegenerative', '/ˌnjʊərəʊdɪˈdʒenərətɪv/', 'adjective', '{"zh-TW":["神經退化性的"],"en":["relating to the progressive loss of nerve cell function"]}', NULL, 'neurodegenerative disease / neurodegenerative condition / neurodegenerative process', '[{"en":"Alzheimer''s disease is the most common neurodegenerative disorder.","zh-TW":"阿茲海默症是最常見的神經退化性疾病。"},{"en":"Research into neurodegenerative diseases focuses on early biomarkers.","zh-TW":"神經退化性疾病的研究集中於早期生物標誌物。"}]', '{"noun":"neurodegeneration"}', NULL, 5, 4448, NULL),
(4449, 'neurology', '/njʊˈrɒlədʒi/', 'noun', '{"zh-TW":["神經學；神經科"],"en":["the branch of medicine dealing with disorders of the nervous system"]}', NULL, 'neurology consultation / neurology department', '[{"en":"The neurologist found no abnormalities in the brain scan.","zh-TW":"神經科醫生在腦部掃描中未發現異常。"},{"en":"Headaches that persist should be evaluated by neurology.","zh-TW":"持續的頭痛應由神經科評估。"}]', '{"noun":"neurologist","adjective":"neurological"}', NULL, 3, 4449, NULL);
