(4450, 'neutral', '/ˈnjuːtrəl/', 'adjective', '{"zh-TW":["中立的","中性的"],"en":["not supporting either side","without strong characteristics"]}', '{"root":{"text":"neutr","meaning":"neither (都不)"},"suffix":{"text":"-al","meaning":"...的"}}', 'remain neutral / neutral position', '[{"en":"The mediator must remain neutral.","zh-TW":"調解人必須保持中立。"},{"en":"Please use a neutral tone in the email.","zh-TW":"請在郵件中使用中性語氣。"}]', '{"noun":"neutrality","verb":"neutralize","adverb":"neutrally"}', NULL, 3, 4450, NULL),
(4451, 'nevertheless', '/ˌnɛvərðəˈlɛs/', 'adverb', '{"zh-TW":["然而；儘管如此"],"en":["in spite of that; however"]}', NULL, 'nevertheless, ... / but nevertheless', '[{"en":"The project was risky; nevertheless, we proceeded.","zh-TW":"項目有風險；然而我們繼續了。"},{"en":"He was tired; nevertheless, he finished the report.","zh-TW":"他很累；儘管如此他完成了報告。"}]', NULL, NULL, 4, 4451, NULL),
(4452, 'new', 'njuː', 'adjective', '{"zh-TW":["新的；新型的","近期的"],"en":["recently made or acquired","not used before"]}', NULL, 'new product/new employee', '[{"en":"Welcome our new team members.","zh-TW":"歡迎我們的新團隊成員。"}]', '{"noun":"newness","adverb":"newly"}', NULL, 1, 4452, NULL),
(4453, 'new business development', '/njuː ˈbɪznɪs dɪˈveləpmənt/', 'noun', '{"zh-TW":["新業務開發"],"en":["activities focused on identifying and securing new revenue opportunities"]}', NULL, 'lead new business development / new business development strategy', '[{"en":"The company hired a VP to lead new business development in Asia.","zh-TW":"公司聘請了一位副總裁領導亞洲的新業務開發。"},{"en":"New business development requires strong networking and negotiation skills.","zh-TW":"新業務開發需要強大的網絡建立和談判技能。"}]', NULL, NULL, 5, 4453, NULL),
(4454, 'new hire', '/njuː haɪər/', 'noun', '{"zh-TW":["新進員工"],"en":["a person recently employed by an organization"]}', NULL, 'onboard a new hire / new hire training', '[{"en":"New hires receive a two-week orientation program.","zh-TW":"新進員工接受兩週的入職培訓計劃。"},{"en":"The company welcomed 50 new hires in the first quarter.","zh-TW":"公司在第一季度歡迎了50名新進員工。"}]', NULL, NULL, 3, 4454, NULL),
(4455, 'new market', '/njuː ˈmɑːrkɪt/', 'noun', '{"zh-TW":["新市場"],"en":["a geographic area or customer segment a company is entering for the first time"]}', NULL, 'enter a new market / explore a new market', '[{"en":"The company entered three new markets in Southeast Asia.","zh-TW":"公司進入了東南亞三個新市場。"},{"en":"Research is critical before entering a new market.","zh-TW":"在進入新市場前，研究至關重要。"}]', NULL, NULL, 4, 4455, NULL),
(4456, 'new product development', '/njuː ˈprɒdʌkt dɪˈveləpmənt/', 'noun', '{"zh-TW":["新產品開發"],"en":["the process of creating and bringing a new product to market"]}', NULL, 'lead new product development / accelerate new product development', '[{"en":"New product development cycles were shortened by 30%.","zh-TW":"新產品開發週期縮短了30%。"},{"en":"New product development is funded by retained earnings.","zh-TW":"新產品開發由留存盈利資助。"}]', '{"abbreviation":"NPD"}', NULL, 5, 4456, NULL),
(4457, 'news', '/njuːz/', 'noun', '{"zh-TW":["新聞；消息"],"en":["new information about recent events"]}', NULL, 'breaking news / good news', '[{"en":"I have good news about the contract.","zh-TW":"我有關於合約的好消息。"},{"en":"The news spread quickly across the company.","zh-TW":"消息在公司內迅速傳開。"}]', '{"noun":"news","noun2":"newspaper","noun3":"newsletter","adjective":"newsworthy"}', NULL, 1, 4457, NULL),
(4458, 'newsletter', '/ˈnjuːzletər/', 'noun', '{"zh-TW":["電子報；通訊"],"en":["a regularly distributed email or publication with company news and updates"]}', NULL, 'send a newsletter / newsletter subscription / weekly newsletter', '[{"en":"The company newsletter is sent to 50,000 subscribers monthly.","zh-TW":"公司電子報每月發送給50,000名訂閱者。"},{"en":"The newsletter featured product updates and customer success stories.","zh-TW":"電子報包含產品更新和客戶成功故事。"}]', '{"plural":"newsletters"}', NULL, 4, 4458, NULL),
(4459, 'nexus', '/ˈneksəs/', 'noun', '{"zh-TW":["核心；紐帶；關聯"],"en":["a connection or series of connections linking things; a central point"]}', NULL, 'nexus of power / causal nexus / form a nexus', '[{"en":"The city became the nexus of global financial activity.","zh-TW":"該城市成為全球金融活動的核心。"},{"en":"The report explores the nexus between poverty and education.","zh-TW":"報告探討了貧困與教育之間的紐帶。"}]', NULL, NULL, 2, 4459, NULL),
(4460, 'nice', '/naɪs/', 'adjective', '{"zh-TW":["好的；友善的"],"en":["pleasant; agreeable"]}', NULL, 'nice to meet you / nice work', '[{"en":"Nice to meet you.","zh-TW":"很高興認識你。"},{"en":"Nice work on the presentation!","zh-TW":"簡報做得好！"}]', '{"adjective":"nice","adverb":"nicely"}', NULL, 1, 4460, NULL),
(4461, 'niche', 'niːʃ', 'noun', '{"zh-TW":["細分市場；利基","適合的地方"],"en":["a specialized market segment","a perfect fit"]}', NULL, 'niche market/find a niche', '[{"en":"Our product targets a niche market.","zh-TW":"我們的產品針對細分市場。"}]', '{"adjective":"niche-focused"}', NULL, 2, 4461, NULL),
(4462, 'niche market', '/nɪtʃ ˈmɑːrkɪt/', 'noun', '{"zh-TW":["利基市場；小眾市場"],"en":["a specialized segment of a larger market"]}', NULL, 'target a niche market / niche market strategy', '[{"en":"The startup found success by targeting a niche market.","zh-TW":"這家初創公司透過針對利基市場取得了成功。"},{"en":"Serving a niche market allows for premium pricing.","zh-TW":"服務利基市場允許進行溢價定價。"}]', NULL, NULL, 4, 4462, NULL),
(4463, 'night', '/naɪt/', 'noun', '{"zh-TW":["夜晚"],"en":["the time when it is dark"]}', NULL, 'night shift / overnight', '[{"en":"Some staff work the night shift.","zh-TW":"有些員工上夜班。"},{"en":"We can ship it overnight.","zh-TW":"我們可以隔夜寄送。"}]', '{"noun":"night","adjective":"nightly","adverb":"overnight"}', NULL, 2, 4463, NULL),
(4464, 'nimble', '/''nɪmbəl/', 'adjective', '{"zh-TW":["靈活的；敏捷的"],"en":["quick and light in movement or action; agile; able to think and understand quickly"]}', NULL, 'nimble organization / nimble response / stay nimble', '[{"en":"A nimble startup can react to market changes faster than a large corporation.","zh-TW":"靈活的新創公司可以比大公司更快地對市場變化做出反應。"},{"en":"Her nimble mind allowed her to quickly identify the root cause of the problem.","zh-TW":"她靈敏的思維使她能夠迅速識別問題的根本原因。"}]', '{"adverb":"nimbly","noun":"nimbleness"}', NULL, 2, 4464, NULL),
(4465, 'nitrogen cycle', '/ˈnaɪtrədʒən ˈsaɪkəl/', 'noun', '{"zh-TW":["氮循環"],"en":["the series of processes by which nitrogen is converted between its various forms"]}', NULL, 'disrupt the nitrogen cycle / understand the nitrogen cycle / nitrogen cycle imbalance', '[{"en":"Excessive fertilizer use disrupts the nitrogen cycle and causes water pollution.","zh-TW":"過度使用化肥破壞了氮循環並造成水污染。"},{"en":"The nitrogen cycle is fundamental to maintaining soil fertility.","zh-TW":"氮循環對維持土壤肥力至關重要。"}]', NULL, NULL, 5, 4465, NULL),
(4466, 'no-action letter', '/noʊ ˈækʃən ˈletər/', 'noun', '{"zh-TW":["無異議函；不採取行動聲明"],"en":["a regulatory response indicating no action will be taken against a practice"]}', NULL, 'obtain a no-action letter / apply for a no-action letter', '[{"en":"The company received a no-action letter from the regulator.","zh-TW":"公司從監管機構收到了無異議函。"},{"en":"A no-action letter provides regulatory certainty for planned activities.","zh-TW":"無異議函為計劃活動提供了監管確定性。"}]', NULL, NULL, 5, 4466, NULL),
(4467, 'no-show', '/''nəʊ ʃəʊ/', 'noun', '{"zh-TW":["未露面者；未按預訂到達的客人"],"en":["a person who has made a reservation but fails to arrive"]}', NULL, 'no-show fee / hotel no-show / flight no-show', '[{"en":"A no-show for a non-refundable reservation results in a full charge.","zh-TW":"未能出現的不可退款預訂將被全額收費。"},{"en":"Airlines overbook flights specifically to compensate for expected no-shows.","zh-TW":"航空公司超額預訂航班，就是為了補償預期的未露面乘客。"}]', NULL, NULL, 3, 4467, NULL),
(4468, 'noise', '/nɔɪz/', 'noun', '{"zh-TW":["噪音；雜訊"],"en":["unwanted sound"]}', NULL, 'make noise / noise pollution', '[{"en":"Noise pollution affects worker productivity.","zh-TW":"噪音污染影響工人生產力。"},{"en":"The data contains too much noise.","zh-TW":"數據中有太多雜訊。"}]', '{"noun":"noise","adjective":"noisy","adverb":"noisily"}', NULL, 2, 4468, NULL),
(4469, 'nomadic', '/''nəʊˈmædɪk/', 'adjective', '{"zh-TW":["游牧的；流浪的"],"en":["living the life of a nomad; wandering from place to place"]}', NULL, 'nomadic lifestyle / nomadic tribe / nomadic culture', '[{"en":"He lived a nomadic lifestyle, moving to a new city every six months.","zh-TW":"他過著游牧式的生活，每六個月搬到一個新城市。"},{"en":"Nomadic peoples traditionally follow their livestock across vast territories.","zh-TW":"游牧民族傳統上跟隨牲畜穿越廣闊的領土。"}]', '{"noun":"nomad"}', NULL, 3, 4469, NULL),
(4470, 'nominal', '/ˈnɒmɪnəl/', 'adjective', '{"zh-TW":["名義上的","象徵性的"],"en":["in name only","very small"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-al","meaning":"...的"}}', 'nominal fee / nominal value', '[{"en":"They charge a nominal fee for the service.","zh-TW":"他們收取象徵性費用。"},{"en":"He is the nominal leader of the organization.","zh-TW":"他是名義上的領導人。"}]', '{"adverb":"nominally","verb":"nominate","noun":"nomination"}', NULL, 3, 4470, 896),
(4471, 'nominal growth', '/ˈnɒmɪnəl ɡroʊθ/', 'noun', '{"zh-TW":["名目增長"],"en":["growth measured in current prices, not adjusted for inflation"]}', NULL, 'report nominal growth / compare nominal and real growth', '[{"en":"Nominal growth was 8%, but real growth after inflation was only 3%.","zh-TW":"名目增長為8%，但扣除通脹後的實際增長僅為3%。"},{"en":"Investors track both nominal and real growth to understand true economic performance.","zh-TW":"投資者追蹤名目和實際增長以了解真實的經濟表現。"}]', '{"opposite":"real growth"}', NULL, 5, 4471, NULL),
(4472, 'nominal rate', '/''nɒmɪnəl reɪt/', 'noun', '{"zh-TW":["名義利率；名目利率"],"en":["the interest rate stated on a financial instrument, without adjusting for inflation"]}', NULL, 'nominal rate versus real rate / apply a nominal rate / nominal rate comparison', '[{"en":"The nominal rate on the savings account was three percent.","zh-TW":"儲蓄帳戶的名義利率為三%。"},{"en":"Investors must distinguish between nominal rates and real rates to understand actual returns.","zh-TW":"投資者必須區分名義利率和實際利率，才能了解實際回報。"}]', '{"adjective":"nominal"}', NULL, 4, 4472, NULL),
(4473, 'nominal return', '/ˈnɒmɪnəl rɪˈtɜːrn/', 'noun', '{"zh-TW":["名義報酬率"],"en":["the rate of return on an investment without adjusting for inflation"]}', NULL, 'compare nominal return / nominal return on investment / convert to real return', '[{"en":"A ten percent nominal return is only five percent in real terms if inflation is five percent.","zh-TW":"如果通膨為百分之五，百分之十的名義報酬率實際上只有百分之五。"},{"en":"Nominal returns can be misleading during high inflation periods.","zh-TW":"高通膨時期，名義報酬率可能會造成誤導。"}]', NULL, NULL, 5, 4473, NULL),
(4474, 'nominal value', '/ˈnɒmɪnəl ˈvæljuː/', 'noun', '{"zh-TW":["名義價值；面值"],"en":["the stated face value of a security or currency, not adjusted for inflation"]}', NULL, 'trade at nominal value / below nominal value', '[{"en":"Bonds are issued at nominal value and redeemed at maturity.","zh-TW":"債券按面值發行並在到期時贖回。"},{"en":"The shares have a nominal value of one dollar each.","zh-TW":"股票的名義價值為每股一美元。"}]', NULL, NULL, 5, 4474, NULL),
(4475, 'nominate', '/ˈnɒmɪneɪt/', 'verb', '{"zh-TW":["提名；任命"],"en":["to suggest someone for a position"]}', '{"root":{"text":"nomin","meaning":"name (名字)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'nominate sb. for / be nominated', '[{"en":"She was nominated for Employee of the Year.","zh-TW":"她被提名為年度最佳員工。"},{"en":"The board nominated him as chairman.","zh-TW":"董事會提名他為主席。"}]', '{"noun":"nomination, nominee","adjective":"nominal"}', NULL, 3, 4475, NULL),
(4476, 'non-alcoholic', '/ˌnɒn ˌælkəˈhɒlɪk/', 'adjective', '{"zh-TW":["不含酒精的；非酒精的"],"en":["containing no alcohol"]}', NULL, 'non-alcoholic beverage / non-alcoholic option', '[{"en":"The menu includes a wide range of non-alcoholic beverages.","zh-TW":"菜單包含各種不含酒精的飲料。"},{"en":"She ordered a non-alcoholic cocktail.","zh-TW":"她點了一杯非酒精雞尾酒。"}]', NULL, NULL, 5, 4476, NULL),
(4477, 'non-compete', '/nɒn kəmˈpiːt/', 'noun', '{"zh-TW":["競業禁止協議"],"en":["an agreement not to work for competitors after leaving"]}', NULL, 'non-compete clause / sign a non-compete', '[{"en":"The employee signed a non-compete agreement.","zh-TW":"員工簽署了競業禁止協議。"},{"en":"The non-compete clause lasts for two years after termination.","zh-TW":"競業禁止條款在終止後持續兩年。"}]', NULL, NULL, 4, 4477, NULL),
(4478, 'non-compete clause', '/nɒn kəmˈpiːt klɔːz/', 'noun', '{"zh-TW":["競業禁止條款"],"en":["a contract term restricting an employee from working for competitors"]}', NULL, 'sign a non-compete clause / enforce a non-compete clause', '[{"en":"The non-compete clause prevented him from joining a rival for two years.","zh-TW":"競業禁止條款阻止他在兩年內加入競爭對手。"},{"en":"Courts sometimes invalidate overly broad non-compete clauses.","zh-TW":"法院有時會宣告過於廣泛的競業禁止條款無效。"}]', NULL, NULL, 5, 4478, NULL),
(4479, 'non-core asset', '/nɒn kɔːr ˈæset/', 'noun', '{"zh-TW":["非核心資產"],"en":["an asset that is not central to a company''s main business activities"]}', NULL, 'dispose of non-core assets / non-core asset sale', '[{"en":"The company sold its non-core assets to focus on core operations.","zh-TW":"公司出售了非核心資產以專注於核心業務。"},{"en":"Proceeds from non-core asset sales were used to reduce debt.","zh-TW":"非核心資產出售所得用於減少債務。"}]', NULL, NULL, 5, 4479, NULL),
(4480, 'non-current assets', '/nɒn ˈkɜːrənt ˈæsets/', 'noun', '{"zh-TW":["非流動資產；長期資產"],"en":["assets not expected to be converted into cash within one year"]}', NULL, 'report non-current assets / invest in non-current assets', '[{"en":"Property and equipment are classified as non-current assets.","zh-TW":"房產和設備歸類為非流動資產。"},{"en":"Non-current assets are recorded at cost minus accumulated depreciation.","zh-TW":"非流動資產以成本減去累計折舊記錄。"}]', NULL, NULL, 5, 4480, NULL),
(4481, 'non-disclosure agreement', '/nɒn dɪsˈkloʊʒər əˈɡriːmənt/', 'noun', '{"zh-TW":["保密協議"],"en":["a legal contract preventing parties from sharing confidential information"]}', NULL, 'sign an NDA / non-disclosure agreement clause / breach of NDA', '[{"en":"All new hires sign a non-disclosure agreement on day one.","zh-TW":"所有新員工在第一天簽署保密協議。"},{"en":"The non-disclosure agreement protected trade secrets during the negotiations.","zh-TW":"保密協議在談判期間保護了商業機密。"}]', '{"abbreviation":"NDA"}', NULL, 5, 4481, NULL),
(4482, 'non-linear', '/nɒn ˈlɪniər/', 'adjective', '{"zh-TW":["非線性的"],"en":["not following a linear or predictable path"]}', NULL, 'non-linear thinking / non-linear model / non-linear dynamics', '[{"en":"Non-linear dynamics can produce unexpected outcomes from small changes.","zh-TW":"非線性動力學可以從微小變化中產生意想不到的結果。"},{"en":"Learning is a non-linear process that involves revision and refinement.","zh-TW":"學習是一個涉及修改和完善的非線性過程。"}]', '{"noun":"non-linearity"}', NULL, 4, 4482, NULL),
(4483, 'non-negotiable', '/''nɒn nɪˌɡəʊʃɪˌeɪbəl/', 'adjective', '{"zh-TW":["不可商量的；不可談判的"],"en":["not open to discussion or alteration; fixed and not subject to change"]}', NULL, 'non-negotiable requirement / non-negotiable term / remain non-negotiable', '[{"en":"Safety standards are non-negotiable and cannot be compromised for cost savings.","zh-TW":"安全標準是不可商量的，不能因成本節省而妥協。"},{"en":"The minimum salary requirement was non-negotiable for the candidate.","zh-TW":"最低薪資要求對候選人來說是不可商量的。"}]', '{"noun":"non-negotiability"}', NULL, 5, 4483, NULL),
(4484, 'non-performing loan', '/nɒn pəˈfɔːrmɪŋ loʊn/', 'noun', '{"zh-TW":["不良貸款"],"en":["a loan on which the borrower has defaulted on repayments"]}', NULL, 'write off non-performing loans / increase in non-performing loans', '[{"en":"The bank''s ratio of non-performing loans rose during the downturn.","zh-TW":"銀行的不良貸款比率在低迷期間上升了。"},{"en":"Non-performing loans are classified after 90 days of missed payments.","zh-TW":"不良貸款在錯過90天還款後分類。"}]', '{"abbreviation":"NPL"}', NULL, 5, 4484, NULL),
(4485, 'non-recurring charge', '/nɒn rɪˈkɜːrɪŋ tʃɑːrdʒ/', 'noun', '{"zh-TW":["一次性費用；非經常性費用"],"en":["a one-time expense that is not expected to recur in future periods"]}', NULL, 'record a non-recurring charge / non-recurring charge disclosure', '[{"en":"The company reported a non-recurring charge for restructuring costs.","zh-TW":"公司報告了一項重組費用的非經常性費用。"},{"en":"Non-recurring charges are excluded from adjusted earnings calculations.","zh-TW":"非經常性費用從調整後盈利計算中排除。"}]', NULL, NULL, 5, 4485, NULL),
(4486, 'non-recurring expense', '/ˌnɒn rɪˈkɜːrɪŋ ɪkˈspens/', 'noun', '{"zh-TW":["一次性費用；非經常性費用"],"en":["an unusual or infrequent cost not expected to occur again in normal operations"]}', NULL, 'report a non-recurring expense / exclude non-recurring expenses', '[{"en":"The restructuring charge was classified as a non-recurring expense.","zh-TW":"重組費用被歸類為一次性費用。"},{"en":"Analysts often exclude non-recurring expenses to assess underlying profitability.","zh-TW":"分析師通常排除非經常性費用以評估基礎盈利能力。"}]', NULL, NULL, 5, 4486, NULL),
(4487, 'non-refundable', '/ˌnɒn rɪˈfʌndəbəl/', 'adjective', '{"zh-TW":["不可退款的"],"en":["not eligible for a refund"]}', NULL, 'non-refundable deposit / non-refundable booking', '[{"en":"The advance booking rate is non-refundable.","zh-TW":"提前預訂價格不可退款。"},{"en":"Read the terms carefully as some rates are non-refundable.","zh-TW":"請仔細閱讀條款，因為有些價格不可退款。"}]', NULL, NULL, 5, 4487, NULL),
(4488, 'non-verbal communication', '/''nɒn vɜːrbəl kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["非語言溝通；非口頭交流"],"en":["the transmission of information through body language, gestures, facial expressions, and tone of voice"]}', NULL, 'understand non-verbal communication / non-verbal communication cues / interpret non-verbal communication', '[{"en":"Non-verbal communication can sometimes convey more than words alone.","zh-TW":"非語言溝通有時比言語本身傳達更多信息。"},{"en":"Training in non-verbal communication helps negotiators read their counterpart''s true feelings.","zh-TW":"非語言溝通培訓幫助談判者讀懂對方的真實感受。"}]', NULL, NULL, 5, 4488, NULL),
(4489, 'nondisclosure', '/ˌnɒndɪsˈkləʊʒər/', 'noun', '{"zh-TW":["保密；不披露"],"en":["the practice of keeping information confidential"]}', NULL, 'nondisclosure requirement / nondisclosure policy', '[{"en":"The nondisclosure requirement applies to all contractors.","zh-TW":"保密要求適用於所有承包商。"},{"en":"Violation of the nondisclosure policy may result in termination.","zh-TW":"違反保密政策可能導致解僱。"}]', NULL, NULL, 5, 4489, NULL),
(4490, 'nonstop', '/ˈnɒnstɒp/', 'adjective', '{"zh-TW":["不停站的；直飛的"],"en":["continuing without any stops"]}', NULL, 'nonstop flight / nonstop service', '[{"en":"There is a nonstop flight from Taipei to New York.","zh-TW":"台北到紐約有直飛航班。"},{"en":"We prefer nonstop flights for long-distance travel.","zh-TW":"長途旅行我們偏好直飛航班。"}]', '{"adverb":"nonstop"}', NULL, 3, 4490, NULL),
(4491, 'nonverbal cue', '/''nɒnˌvɜːrbəl kjuː/', 'noun', '{"zh-TW":["非語言暗示；非口頭提示"],"en":["a signal conveyed through body language, facial expression, or gesture rather than words"]}', NULL, 'read nonverbal cues / pick up on nonverbal cues / interpret nonverbal cues', '[{"en":"She was skilled at reading nonverbal cues during negotiations.","zh-TW":"她擅長在談判中解讀非語言暗示。"},{"en":"Children learn to interpret nonverbal cues long before they can speak fluently.","zh-TW":"兒童在能流利說話之前就學會了解讀非語言暗示。"}]', '{"adjective":"nonverbal","adverb":"nonverbally"}', NULL, 5, 4491, NULL),
(4492, 'norm', '/nɔːrm/', 'noun', '{"zh-TW":["規範；標準","常態"],"en":["a standard","the usual state"]}', '{"root":{"text":"norm","meaning":"rule (規則)"}}', 'social norm / above the norm', '[{"en":"Working from home has become the norm.","zh-TW":"在家工作已成為常態。"},{"en":"Safety standards exceed industry norms.","zh-TW":"安全標準超過行業規範。"}]', '{"adjective":"normal, normative","verb":"normalize","adverb":"normally"}', NULL, 1, 4492, NULL),
(4493, 'norm diffusion', '/nɔːrm dɪˈfjuːʒən/', 'noun', '{"zh-TW":["規範擴散"],"en":["the spread of social or international norms from one group to another"]}', NULL, 'international norm diffusion / norm diffusion process / facilitate norm diffusion', '[{"en":"Norm diffusion explains how human rights standards spread globally.","zh-TW":"規範擴散解釋了人權標準如何在全球傳播。"},{"en":"Social movements accelerate norm diffusion by changing public discourse.","zh-TW":"社會運動通過改變公眾話語來加速規範擴散。"}]', NULL, NULL, 5, 4493, NULL),
(4494, 'normal', '/ˈnɔːrməl/', 'adjective', '{"zh-TW":["正常的；一般的","正常的"],"en":["usual; typical; expected","usual; typical"]}', '{"root":{"text":"norm","meaning":"rule (規則)"},"suffix":{"text":"-al","meaning":"...的"}}', 'return to normal / normal procedure; return to normal / normal hours / new normal', '[{"en":"Business operations have returned to normal.","zh-TW":"業務運營已恢復正常。"},{"en":"This is normal procedure for new hires.","zh-TW":"這是新員工的正常流程。"},{"en":"Business hours have returned to normal.","zh-TW":"營業時間已恢復正常。"},{"en":"Remote work is the new normal.","zh-TW":"遠程工作是新常態。"}]', '{"noun":"normality, norm","verb":"normalize","adverb":"normally"}', NULL, 2, 4494, NULL),
(4495, 'normal operating conditions', '/ˈnɔːrməl ˈɒpəreɪtɪŋ kənˈdɪʃənz/', 'noun', '{"zh-TW":["正常運營條件"],"en":["the standard conditions under which a business typically operates"]}', NULL, 'maintain normal operating conditions / return to normal operating conditions', '[{"en":"The warranty is valid under normal operating conditions only.","zh-TW":"保固僅在正常運營條件下有效。"},{"en":"Production resumed at full capacity after returning to normal operating conditions.","zh-TW":"在恢復正常運營條件後，生產恢復了全速運轉。"}]', NULL, NULL, 5, 4495, NULL),
(4496, 'normalization', '/ˌnɔːrməlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["正常化；規範化"],"en":["the process of adjusting data or financial figures to reflect normal operating conditions"]}', NULL, 'apply normalization / earnings normalization', '[{"en":"Analysts apply normalization adjustments to remove one-time items from earnings.","zh-TW":"分析師應用正常化調整以從盈利中剔除一次性項目。"},{"en":"Interest rate normalization is the process of returning to typical rate levels.","zh-TW":"利率正常化是恢復到典型利率水平的過程。"}]', '{"verb":"normalize","adjective":"normalized"}', NULL, 5, 4496, NULL),
(4497, 'normative', '/ˈnɔːrmətɪv/', 'adjective', '{"zh-TW":["規範的；標準的"],"en":["relating to or deriving from a standard or norm"]}', NULL, 'normative framework / normative standards / normative analysis', '[{"en":"The study offers both normative and descriptive insights.","zh-TW":"該研究提供了規範性和描述性的見解。"},{"en":"Normative guidelines help organizations maintain ethical conduct.","zh-TW":"規範準則幫助組織維持道德行為。"}]', '{"noun":"norm","adverb":"normatively"}', NULL, 3, 4497, NULL),
(4498, 'normative economics', '/ˈnɔːrmətɪv ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["規範經濟學"],"en":["the branch of economics dealing with value judgments about what the economy ought to be"]}', NULL, 'apply normative economics / normative economics debate / normative vs positive economics', '[{"en":"Normative economics discusses what policies governments should implement.","zh-TW":"規範經濟學討論政府應該實施什麼政策。"},{"en":"The debate over income redistribution falls within normative economics.","zh-TW":"關於收入再分配的辯論屬於規範經濟學範疇。"}]', NULL, NULL, 5, 4498, NULL),
(4499, 'north', '/nɔːrθ/', 'noun', '{"zh-TW":["北方"],"en":["the direction opposite to south"]}', NULL, 'north of / up north', '[{"en":"The factory is north of the city.","zh-TW":"工廠在城市北邊。"},{"en":"We are expanding up north.","zh-TW":"我們正在向北方擴展。"}]', '{"noun":"north","adjective":"northern","adverb":"northward"}', NULL, 2, 4499, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4500, 'notable', '/ˈnoʊtəbl/', 'adjective', '{"zh-TW":["值得注意的；顯著的"],"en":["worthy of attention; remarkable"]}', '{"root":{"text":"not","meaning":"mark (標記)"},"suffix":{"text":"-able","meaning":"能...的"}}', 'notable achievement / most notably', '[{"en":"There has been a notable improvement in sales.","zh-TW":"銷售額有顯著改善。"},{"en":"The city is notable for its architecture.","zh-TW":"這城市以建築聞名。"}]', '{"adverb":"notably","noun":"notability"}', NULL, 3, 4500, NULL),
(4501, 'notarize', '/ˈnəʊtəraɪz/', 'verb', '{"zh-TW":["公證；公證認證"],"en":["to have a document officially certified by a notary"]}', NULL, 'notarize a document / notarize a signature', '[{"en":"The contract must be notarized before it is valid.","zh-TW":"合約在公證前無效。"},{"en":"She took the deed to a notary to have it notarized.","zh-TW":"她將契約帶到公證人處進行公證。"}]', '{"noun":"notarization","noun2":"notary","adjective":"notarized"}', NULL, 3, 4501, NULL),
(4502, 'notation', '/noʊˈteɪʃən/', 'noun', '{"zh-TW":["符號；標記"],"en":["a system of symbols used to represent information"]}', NULL, 'accounting notation / mathematical notation / make a notation', '[{"en":"The accountant used standard notation for all financial entries.","zh-TW":"會計師對所有財務分錄使用了標準符號。"},{"en":"Please make a notation on the file to indicate the new terms.","zh-TW":"請在檔案上作標記以指明新條款。"}]', '{"verb":"notate","adjective":"notated"}', NULL, 3, 4502, NULL),
(4503, 'note', '/noʊt/', 'noun', '{"zh-TW":["筆記；注意"],"en":["a short written message","to pay attention to"]}', NULL, 'take note / please note', '[{"en":"Please note the new office hours.","zh-TW":"請注意新的辦公時間。"},{"en":"I took notes during the meeting.","zh-TW":"我在會議中做了筆記。"}]', '{"noun":"note","verb":"note","adjective":"noteworthy","noun2":"notebook"}', NULL, 1, 4503, NULL),
(4504, 'note payable', '/noʊt ˈpeɪəbəl/', 'noun', '{"zh-TW":["應付票據"],"en":["a written promise to pay a specified amount by a certain date"]}', NULL, 'issue a note payable / note payable balance', '[{"en":"The company issued a note payable to finance the equipment.","zh-TW":"公司發出應付票據為設備融資。"},{"en":"Notes payable are classified under current or non-current liabilities.","zh-TW":"應付票據根據期限歸類為流動或非流動負債。"}]', NULL, NULL, 4, 4504, NULL),
(4505, 'notice', '/ˈnoʊtɪs/', 'noun', '{"zh-TW":["通知；公告","注意"],"en":["a written announcement","attention"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ice","meaning":"名詞後綴"}}', 'give notice / at short notice / until further notice', '[{"en":"Please give two weeks'' notice before resigning.","zh-TW":"辭職前請提前兩週通知。"},{"en":"The change takes effect until further notice.","zh-TW":"變更持續有效直到另行通知。"}]', '{"adjective":"noticeable","adverb":"noticeably","verb":"notice"}', NULL, 2, 4505, 398),
(4506, 'notice of termination', '/ˈnoʊtɪs əv ˌtɜːrmɪˈneɪʃən/', 'noun', '{"zh-TW":["終止通知"],"en":["official written communication ending a contract or employment"]}', NULL, 'issue a notice of termination / receive a notice of termination', '[{"en":"The landlord issued a notice of termination due to unpaid rent.","zh-TW":"房東因未付租金發出了終止通知。"},{"en":"A notice of termination must follow the contractually agreed process.","zh-TW":"終止通知必須遵循合約約定的程序。"}]', NULL, NULL, 5, 4506, NULL),
(4507, 'notice period', '/ˈnoʊtɪs ˈpɪəriəd/', 'noun', '{"zh-TW":["通知期；預告期"],"en":["the time between giving notice and the last working day"]}', NULL, 'serve a notice period / one-month notice period / waive the notice period', '[{"en":"She served a two-week notice period before leaving.","zh-TW":"她在離職前履行了兩週的通知期。"},{"en":"The contract required a three-month notice period.","zh-TW":"合同要求三個月的通知期。"}]', NULL, NULL, 5, 4507, NULL),
(4508, 'notification', 'ˌnoʊtɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["通知；公告","提醒"],"en":["an official message or alert","an announcement"]}', NULL, 'send a notification/receive notification', '[{"en":"You will receive a notification by email.","zh-TW":"您將通過電子郵件收到通知。"}]', '{"verb":"notify","adjective":"notified"}', NULL, 4, 4508, 599),
(4509, 'notify', '/ˈnoʊtɪfaɪ/', 'verb', '{"zh-TW":["通知；告知"],"en":["to formally inform someone"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ify","meaning":"使...化"}}', 'notify sb. of sth. / notify in writing', '[{"en":"We will notify you of any schedule changes.","zh-TW":"我們會通知您時間表的變更。"},{"en":"All employees must be notified in advance.","zh-TW":"所有員工必須提前被通知。"}]', '{"noun":"notification","adjective":"notifiable"}', NULL, 2, 4509, 40),
(4510, 'notion', '/ˈnoʊʃən/', 'noun', '{"zh-TW":["概念；想法"],"en":["a concept or belief"]}', '{"root":{"text":"not","meaning":"know (知道)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'the notion that / preconceived notion', '[{"en":"She rejected the notion that women cannot lead.","zh-TW":"她駁斥了女性不能領導的觀念。"},{"en":"He has no notion of the difficulty.","zh-TW":"他不知道有多困難。"}]', '{"adjective":"notional"}', NULL, 2, 4510, NULL),
(4511, 'notional', '/ˈnəʊʃənəl/', 'adjective', '{"zh-TW":["名義上的；概念性的"],"en":["existing only in theory or as a concept; relating to the face value of a derivative"]}', NULL, 'notional value / notional amount / notional principal', '[{"en":"The swap has a notional principal of ten million dollars.","zh-TW":"掉期的名義本金為一千萬美元。"},{"en":"The notional cost of the project does not reflect its true economic value.","zh-TW":"該項目的名義成本不反映其真實經濟價值。"}]', '{"adverb":"notionally"}', NULL, 3, 4511, NULL),
(4512, 'notional value', '/ˈnoʊʃənl ˈvæljuː/', 'noun', '{"zh-TW":["名目價值；概念價值"],"en":["the face value of a financial contract used to calculate payments"]}', NULL, 'calculate notional value / notional value of the contract', '[{"en":"The notional value of the interest rate swap was $10 million.","zh-TW":"利率互換的名目價值為1000萬元。"},{"en":"Notional value differs from market value as it does not reflect actual cash flows.","zh-TW":"名目價值與市場價值不同，因為它不反映實際現金流量。"}]', NULL, NULL, 5, 4512, NULL),
(4513, 'notwithstanding', '/ˌnɒtwɪθˈstændɪŋ/', 'preposition', '{"zh-TW":["儘管；雖然"],"en":["in spite of; despite"]}', NULL, 'notwithstanding the fact that', '[{"en":"Notwithstanding the challenges, it was completed on time.","zh-TW":"儘管有挑戰，仍按時完成。"},{"en":"The contract is valid notwithstanding minor errors.","zh-TW":"儘管有小錯，合約仍有效。"}]', NULL, NULL, 5, 4513, NULL),
(4514, 'nourish', '/''nʌrɪʃ/', 'verb', '{"zh-TW":["滋養；給予養分"],"en":["to provide with the food or other substances necessary for growth, health, and good condition"]}', NULL, 'nourish the body / nourish with vitamins / nourishing food', '[{"en":"A bowl of vegetable soup can nourish both the body and soul.","zh-TW":"一碗蔬菜湯可以滋養身體和心靈。"},{"en":"The chef believes that food should nourish as well as delight.","zh-TW":"這位廚師認為食物應該既能滋養又能令人愉悅。"}]', '{"adjective":"nourishing","noun":"nourishment"}', NULL, 3, 4514, NULL),
(4515, 'novel', '/ˈnɒvəl/', 'adjective', '{"zh-TW":["新穎的；新奇的"],"en":["new and original"]}', '{"root":{"text":"nov","meaning":"new (新的)"},"suffix":{"text":"-el","meaning":"後綴"}}', 'novel approach / novel idea', '[{"en":"The team proposed a novel approach.","zh-TW":"團隊提出了新穎的方法。"},{"en":"This is a novel concept in marketing.","zh-TW":"這是行銷的新穎概念。"}]', '{"noun":"novelty, novelist"}', NULL, 2, 4515, NULL),
(4516, 'nuance', '/ˈnjuːɑːns/', 'noun', '{"zh-TW":["細微差別；微妙之處"],"en":["a subtle difference in or shade of meaning"]}', NULL, 'appreciate the nuance / nuance of meaning / cultural nuance', '[{"en":"Understanding the nuance of language is critical for translation.","zh-TW":"理解語言的細微差別對翻譯至關重要。"},{"en":"Her analysis captured the nuances of the political situation.","zh-TW":"她的分析捕捉到了政治局勢的微妙之處。"}]', '{"adjective":"nuanced"}', NULL, 2, 4516, NULL),
(4517, 'nuanced', '/''njuːɑːnst/', 'adjective', '{"zh-TW":["有細微差別的；微妙的"],"en":["characterized by subtle distinctions or variations in expression or understanding"]}', NULL, 'nuanced understanding / nuanced analysis / nuanced approach', '[{"en":"A nuanced understanding of cultural differences is essential for global business.","zh-TW":"對文化差異的微妙理解對全球業務至關重要。"},{"en":"Her nuanced analysis of the market data led to a more accurate forecast.","zh-TW":"她對市場數據的細緻分析帶來了更準確的預測。"}]', '{"noun":"nuance"}', NULL, 3, 4517, NULL),
(4518, 'nuanced approach', '/''njuːɑːnst əˌprəʊtʃ/', 'noun', '{"zh-TW":["細緻入微的方式；微妙的方法"],"en":["a method that considers subtle differences and complexities rather than applying a blanket solution"]}', NULL, 'take a nuanced approach / require a nuanced approach / develop a nuanced approach', '[{"en":"A nuanced approach to negotiation considers the cultural background of each party.","zh-TW":"細緻入微的談判方式考慮了各方的文化背景。"},{"en":"Solving complex social problems requires a nuanced approach rather than simple solutions.","zh-TW":"解決複雜的社會問題需要細緻入微的方式，而非簡單的解決方案。"}]', '{"adjective":"nuanced"}', NULL, 5, 4518, NULL),
(4519, 'number', '/ˈnʌmbər/', 'noun', '{"zh-TW":["數字；號碼"],"en":["a mathematical value","a quantity"]}', NULL, 'a number of / phone number', '[{"en":"A number of clients have complained.","zh-TW":"許多客戶投訴了。"},{"en":"What is your phone number?","zh-TW":"你的電話號碼是什麼？"}]', '{"noun":"number","verb":"number","adjective":"numerous","adjective2":"numerical"}', NULL, 2, 4519, NULL),
(4520, 'numerous', '/ˈnjuːmərəs/', 'adjective', '{"zh-TW":["許多的；眾多的"],"en":["great in number; many"]}', '{"root":{"text":"numer","meaning":"number (數字)"},"suffix":{"text":"-ous","meaning":"充滿...的"}}', 'numerous occasions / numerous studies', '[{"en":"The company received numerous complaints.","zh-TW":"公司收到大量投訴。"},{"en":"She published numerous articles.","zh-TW":"她發表了許多文章。"}]', '{"adverb":"numerously","noun":"number"}', NULL, 3, 4520, NULL),
(4521, 'nunc pro tunc', '/nʌŋk prəʊ tʌŋk/', 'phrase', '{"zh-TW":["事後追溯；補正回溯"],"en":["a Latin phrase meaning ''now for then'', referring to retroactive legal action"]}', NULL, 'nunc pro tunc order / nunc pro tunc amendment / nunc pro tunc entry', '[{"en":"The judge issued a nunc pro tunc order to correct the previous ruling.","zh-TW":"法官發出了追溯令以更正之前的裁定。"},{"en":"A nunc pro tunc amendment corrects a prior court order retroactively.","zh-TW":"追溯修訂可以追溯性地更正之前的法院命令。"}]', NULL, NULL, 5, 4521, NULL),
(4522, 'nurse', '/nɜːrs/', 'noun', '{"zh-TW":["護士"],"en":["a person trained to care for sick people"]}', NULL, 'registered nurse / nurse practitioner', '[{"en":"The company clinic has two registered nurses.","zh-TW":"公司診所有兩位註冊護士。"},{"en":"She trained as a nurse before going into management.","zh-TW":"她在從事管理工作前受過護士訓練。"}]', '{"noun":"nurse","noun2":"nursing","verb":"nurse"}', NULL, 2, 4522, NULL),
(4523, 'nurture', '/ˈnɜːrtʃər/', 'verb', '{"zh-TW":["培養；養育"],"en":["to care for and encourage growth"]}', '{"root":{"text":"nutr","meaning":"nourish (滋養)"},"suffix":{"text":"-ure","meaning":"行為"}}', 'nurture talent / nurture relationships', '[{"en":"The manager nurtures young talent.","zh-TW":"經理培養年輕人才。"},{"en":"Nurture good relationships with clients.","zh-TW":"培養與客戶的良好關係。"}]', '{"noun":"nurture, nurturer","adjective":"nurturing"}', NULL, 3, 4523, NULL),
(4524, 'nutrition', '/''njuːˈtrɪʃən/', 'noun', '{"zh-TW":["營養；營養學"],"en":["the process of providing or obtaining food necessary for health and growth"]}', NULL, 'proper nutrition / nutrition label / nutrition facts', '[{"en":"Good nutrition is essential for physical and mental well-being.","zh-TW":"良好的營養對身體和心理健康至關重要。"},{"en":"Athletes pay close attention to nutrition to optimize their performance.","zh-TW":"運動員密切關注營養以優化他們的表現。"}]', '{"adjective":"nutritional","noun":"nutritionist"}', NULL, 3, 4524, NULL),
(4525, 'oath', '/oʊθ/', 'noun', '{"zh-TW":["宣誓；誓言"],"en":["a formal promise to tell the truth"]}', NULL, 'take an oath / under oath', '[{"en":"She took an oath of office.","zh-TW":"她進行了就職宣誓。"},{"en":"He lied under oath.","zh-TW":"他在宣誓後說謊。"}]', NULL, NULL, 1, 4525, NULL),
(4526, 'obey', '/oʊˈbeɪ/', 'verb', '{"zh-TW":["服從；遵守"],"en":["to do what you are told"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ey","meaning":"hear"}}', 'obey the rules / obey orders', '[{"en":"All employees must obey company regulations.","zh-TW":"所有員工必須遵守公司規定。"},{"en":"Citizens are expected to obey the law.","zh-TW":"公民應遵守法律。"}]', '{"noun":"obedience","adjective":"obedient","adverb":"obediently"}', NULL, 1, 4526, NULL),
(4527, 'object', '/əbˈdʒɛkt/', 'verb', '{"zh-TW":["反對"],"en":["to express disagreement"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"ject","meaning":"throw (投擲)"}}', 'object to sth.', '[{"en":"Several members objected to the proposal.","zh-TW":"幾位成員反對該提案。"},{"en":"No one objected to the new policy.","zh-TW":"沒人反對新政策。"}]', '{"noun":"objection, object","adjective":"objectionable"}', NULL, 2, 4527, NULL),
(4528, 'objective', '/əbˈdʒɛktɪv/', 'noun', '{"zh-TW":["目標；目的"],"en":["a goal or aim"]}', '{"prefix":{"text":"ob-","meaning":"toward"},"root":{"text":"ject","meaning":"throw"},"suffix":{"text":"-ive","meaning":"...的"}}', 'meet an objective / objective assessment', '[{"en":"Our main objective is to increase market share.","zh-TW":"我們的主要目標是增加市場份額。"},{"en":"Try to remain objective when evaluating.","zh-TW":"評估時請保持客觀。"}]', '{"noun":"objectivity","adverb":"objectively"}', NULL, 3, 4528, 163),
(4529, 'objective setting', '/əbˈdʒektɪv ˈsetɪŋ/', 'noun', '{"zh-TW":["目標設定"],"en":["the process of defining specific, measurable goals for individuals or teams"]}', NULL, 'conduct objective setting / annual objective setting', '[{"en":"Objective setting at the start of the year aligns teams with company goals.","zh-TW":"年初的目標設定使團隊與公司目標保持一致。"},{"en":"Clear objective setting improves performance and accountability.","zh-TW":"清晰的目標設定改善了績效和責任感。"}]', NULL, NULL, 5, 4529, NULL),
(4530, 'objective-based', 'əbˈdʒɛktɪv beɪst', 'adjective', '{"zh-TW":["基於目標的；目標導向的","以目標為依據的"],"en":["guided by specific objectives","goal-focused"]}', NULL, 'objective-based management/objective-based review', '[{"en":"Our evaluation is objective-based.","zh-TW":"我們的評估是基於目標的。"}]', NULL, NULL, 5, 4530, NULL),
(4531, 'objectivity', '/ˌɒbdʒekˈtɪvɪti/', 'noun', '{"zh-TW":["客觀性；公正"],"en":["the quality of not being influenced by personal feelings"]}', NULL, 'maintain objectivity / scientific objectivity / lack of objectivity', '[{"en":"Researchers must strive for objectivity in their analysis.","zh-TW":"研究員在分析中必須力求客觀性。"},{"en":"Objectivity is essential for credible journalism.","zh-TW":"客觀性對可信的新聞報導至關重要。"}]', '{"adjective":"objective","adverb":"objectively"}', NULL, 4, 4531, NULL),
(4532, 'obligation', '/ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["義務；責任"],"en":["something you must do"]}', '{"root":{"text":"oblig","meaning":"bind (綁定)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'legal obligation / under no obligation', '[{"en":"You are under no obligation to accept.","zh-TW":"你沒有義務接受。"},{"en":"The company has an obligation to shareholders.","zh-TW":"公司對股東有責任。"}]', '{"verb":"oblige","adjective":"obligatory, obliging"}', NULL, 4, 4532, 399),
(4533, 'observe', '/əbˈzɜːrv/', 'verb', '{"zh-TW":["觀察","遵守"],"en":["to watch carefully","to obey a rule"]}', '{"prefix":{"text":"ob-","meaning":"over"},"root":{"text":"serv","meaning":"watch (看)"}}', 'observe changes / observe rules', '[{"en":"Scientists observed a significant change.","zh-TW":"科學家觀察到顯著變化。"},{"en":"All visitors must observe safety regulations.","zh-TW":"訪客必須遵守安全規定。"}]', '{"noun":"observation, observer","adjective":"observant, observable"}', NULL, 3, 4533, NULL),
(4534, 'obsolete', '/ˈɒbsəliːt/', 'adjective', '{"zh-TW":["過時的；淘汰的"],"en":["no longer in use"]}', '{"prefix":{"text":"ob-","meaning":"away"},"root":{"text":"sol","meaning":"use (使用)"}}', 'become obsolete / obsolete technology', '[{"en":"This software has become obsolete.","zh-TW":"這個軟體已經過時。"},{"en":"New technology rendered the old system obsolete.","zh-TW":"新技術使舊系統過時。"}]', '{"noun":"obsolescence"}', NULL, 3, 4534, NULL),
(4535, 'obstacle', '/ˈɒbstəkl/', 'noun', '{"zh-TW":["障礙"],"en":["something that blocks progress"]}', '{"prefix":{"text":"ob-","meaning":"against"},"root":{"text":"sta","meaning":"stand (站)"}}', 'overcome an obstacle / major obstacle', '[{"en":"Lack of funding is a major obstacle.","zh-TW":"缺乏資金是主要障礙。"},{"en":"She overcame many obstacles.","zh-TW":"她克服了許多障礙。"}]', NULL, NULL, 3, 4535, NULL),
(4536, 'obtain', '/əbˈteɪn/', 'verb', '{"zh-TW":["獲得；取得"],"en":["to get or acquire something","to get something by effort"]}', '{"prefix":{"text":"ob-","meaning":"toward (朝向)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"朝向持有而得到，即「獲得」。"}', 'obtain permission / obtain information / obtain a degree', '[{"en":"You must obtain permission before entering.","zh-TW":"進入前必須獲得許可。"},{"en":"She obtained her PhD from Harvard.","zh-TW":"她從哈佛取得了博士學位。"},{"en":"You must obtain approval before proceeding.","zh-TW":"你必須獲得批准才能繼續。"},{"en":"Details can be obtained from our website.","zh-TW":"詳情可從網站獲取。"}]', '{"adjective":"obtainable"}', NULL, 2, 4536, 41),
(4537, 'obvious', '/ˈɒbviəs/', 'adjective', '{"zh-TW":["明顯的"],"en":["easy to see or understand"]}', '{"prefix":{"text":"ob-","meaning":"in the way"},"root":{"text":"vi","meaning":"way (路)"},"suffix":{"text":"-ous","meaning":"...的"}}', 'obvious reason / it is obvious that', '[{"en":"It is obvious that we need to cut costs.","zh-TW":"很明顯我們需要削減成本。"},{"en":"The answer was obvious to everyone.","zh-TW":"答案對所有人都顯而易見。"}]', '{"adverb":"obviously","noun":"obviousness"}', NULL, 3, 4537, NULL),
(4538, 'occasion', '/əˈkeɪʒən/', 'noun', '{"zh-TW":["場合；時機"],"en":["a particular time or event"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cas","meaning":"fall (落)"}}', 'on this occasion / special occasion / on occasion', '[{"en":"On this occasion, we will make an exception.","zh-TW":"這次我們將破例。"},{"en":"The dinner was a formal occasion.","zh-TW":"晚餐是正式場合。"}]', '{"adjective":"occasional","adverb":"occasionally"}', NULL, 3, 4538, NULL),
(4539, 'occupancy', '/ˈɒkjʊpənsi/', 'noun', '{"zh-TW":["入住率；佔用"],"en":["the use of a room or building"]}', NULL, 'full occupancy / occupancy rate', '[{"en":"The hotel reached full occupancy during the festival.","zh-TW":"節日期間飯店入住率達到最高。"},{"en":"The occupancy rate dropped during the off-season.","zh-TW":"淡季期間入住率下降。"}]', '{"verb":"occupy","adjective":"occupied"}', NULL, 3, 4539, 164),
(4540, 'occupancy rate', '/ˈɒkjʊpənsi reɪt/', 'noun', '{"zh-TW":["入住率；佔用率"],"en":["the percentage of available space that is currently occupied"]}', NULL, 'high occupancy rate / increase occupancy rate / hotel occupancy rate', '[{"en":"The office building maintained a 95% occupancy rate last year.","zh-TW":"辦公樓去年維持了95%的入住率。"},{"en":"A low occupancy rate indicates a weak property market.","zh-TW":"低入住率表明物業市場疲軟。"}]', NULL, NULL, 5, 4540, NULL),
(4541, 'occupational health', '/ˌɒkjʊˈpeɪʃənəl hɛlθ/', 'noun', '{"zh-TW":["職業健康；職業衛生"],"en":["health management relating to work and the workplace"]}', NULL, 'occupational health program / occupational health assessment', '[{"en":"The company offers an occupational health assessment for all employees.","zh-TW":"公司為所有員工提供職業健康評估。"},{"en":"Occupational health programs reduce absenteeism and improve productivity.","zh-TW":"職業健康計劃減少了缺勤並提高了生產力。"}]', NULL, NULL, 5, 4541, NULL),
(4542, 'occupy', '/ˈɒkjupaɪ/', 'verb', '{"zh-TW":["占據；使忙碌","佔據","使忙碌"],"en":["to fill or take up a space or time","to fill or take up space","to keep busy"]}', '{"prefix":{"text":"oc-","meaning":"over (在上)"},"root":{"text":"cupy","meaning":"seize (佔有)"},"logic":"佔有其上，即「占據」。"}', 'occupy a position / occupy space / occupied with; occupy a position / be occupied with', '[{"en":"The meeting occupied the entire morning.","zh-TW":"會議佔了整個早上。"},{"en":"She is occupied with work right now.","zh-TW":"她現在忙於工作。"},{"en":"The department occupies the entire third floor.","zh-TW":"部門佔據了整個三樓。"},{"en":"She has been occupied with the merger.","zh-TW":"她一直忙於合併事宜。"}]', '{"noun":"occupation","adjective":"occupied"}', NULL, 2, 4542, NULL),
(4543, 'occur', '/əˈkɜːr/', 'verb', '{"zh-TW":["發生","想到"],"en":["to happen","to come into mind"]}', '{"prefix":{"text":"oc-","meaning":"toward"},"root":{"text":"cur","meaning":"run (跑)"}}', 'occur frequently / it occurs to sb.', '[{"en":"The error occurred during the update.","zh-TW":"錯誤發生在更新期間。"},{"en":"It never occurred to me to check.","zh-TW":"我從未想到要檢查。"}]', '{"noun":"occurrence"}', NULL, 2, 4543, NULL),
(4544, 'ocean', '/ˈoʊʃən/', 'noun', '{"zh-TW":["海洋"],"en":["a very large area of sea"]}', NULL, 'ocean freight / across the ocean', '[{"en":"Ocean freight is cheaper than air freight.","zh-TW":"海運比空運便宜。"},{"en":"Our products ship across the ocean.","zh-TW":"我們的產品跨洋運送。"}]', '{"noun":"ocean","adjective":"oceanic"}', NULL, 2, 4544, NULL),
(4545, 'ocean freight', '/''əʊʃən freɪt/', 'noun', '{"zh-TW":["海運貨物；遠洋貨運"],"en":["goods transported by sea; the cost of shipping goods by sea"]}', NULL, 'ship via ocean freight / ocean freight schedule / ocean freight rate', '[{"en":"Ocean freight is the most economical option for large, non-urgent shipments.","zh-TW":"海運是大型非緊急貨物最經濟的選擇。"},{"en":"Ocean freight rates have been volatile due to disruptions in global shipping lanes.","zh-TW":"由於全球航運通道的中斷，海運費率一直不穩定。"}]', NULL, NULL, 5, 4545, NULL),
(4546, 'ocean pollution', '/ˈəʊʃən pəˈluːʃən/', 'noun', '{"zh-TW":["海洋污染"],"en":["the contamination of ocean waters with harmful substances"]}', NULL, 'combat ocean pollution / ocean pollution crisis', '[{"en":"Ocean pollution threatens marine biodiversity.","zh-TW":"海洋污染威脅海洋生物多樣性。"},{"en":"Reducing plastic waste is key to addressing ocean pollution.","zh-TW":"減少塑膠廢棄物是解決海洋污染的關鍵。"}]', NULL, NULL, 5, 4546, NULL),
(4547, 'ocean view room', '/ˈəʊʃən vjuː ruːm/', 'noun', '{"zh-TW":["海景房"],"en":["a hotel room with a view of the ocean"]}', NULL, 'book an ocean view room / premium ocean view room', '[{"en":"She splurged on an ocean view room for their honeymoon.","zh-TW":"她為蜜月之旅訂了一間海景房。"},{"en":"Ocean view rooms are among the most popular choices at beach resorts.","zh-TW":"海景房是海灘度假村中最受歡迎的選擇之一。"}]', NULL, NULL, 5, 4547, NULL),
(4548, 'odd', '/ɒd/', 'adjective, noun (plural)', '{"zh-TW":["【主要意義-形容詞】奇怪的；不尋常的","【次要意義-形容詞】奇數的（不能被2整除）","【次要意義-形容詞】剩餘的；臨時的；偶爾的","【次要意義-複數名詞（odds）】機率；可能性；不平等"],"en":["[primary - adjective] strange or unusual","[secondary - adjective] not divisible by two","[secondary - adjective] extra; occasional; not regular","[secondary - plural noun] probability; the likelihood of something happening"]}', NULL, 'odd jobs / odd numbers / at odds with / odds are / against all odds', '[{"en":"The odds of winning the contract are in our favor after the presentation.","zh-TW":"提案後，贏得合約的勝算對我們有利。"},{"en":"He does odd jobs around the office such as filing and photocopying.","zh-TW":"他在辦公室做一些零散工作，如歸檔和影印。"},{"en":"Management was at odds with the union over the new pay structure.","zh-TW":"管理層與工會在新薪酬結構問題上存在分歧。"}]', '{"adverb":"oddly","noun":"oddity"}', 'odds（機率/勝算）、at odds with（與……有分歧）、odd jobs（零散工作）均為 TOEIC 商業文章常見詞彙，考生只知道「奇怪」的意思會造成閱讀障礙。', 1, 4548, NULL),
(4549, 'off-balance sheet', '/ˌɒf ˈbæləns ʃiːt/', 'adjective', '{"zh-TW":["表外的；資產負債表外的"],"en":["not recorded on the main financial statements"]}', NULL, 'off-balance sheet financing / off-balance sheet obligation', '[{"en":"The lease was structured as off-balance sheet financing.","zh-TW":"租賃被結構為表外融資。"},{"en":"New accounting rules brought many off-balance sheet items onto the balance sheet.","zh-TW":"新會計準則將許多表外項目納入了資產負債表。"}]', NULL, NULL, 5, 4549, NULL);